sub_F0EA9F:
	link XIZ,0xfff8	; F0EA9F  link XIZ,0xfff8
	pushw	hl	; F0EAA3  push HL
	pushw	de	; F0EAA4  push DE
	push	xix	; F0EAA5  push XIX
	ld	xbc, (xiz+8)	; F0EAA6  ld XBC,(XIZ+0x08)
	ld	l, (xbc)	; F0EAA9  ld L,(XBC)
	inc	2, xbc	; F0EAAB  inc 2,XBC
	ld	(xiz-8), xbc	; F0EAAD  ld (XIZ+0xf8),XBC
	ld	wa, (xbc)	; F0EAB0  ld WA,(XBC)
	extz	xwa	; F0EAB2  extz XWA
	ld	xix, xwa	; F0EAB4  ld XIX,XWA
