	push	xhl	; F63BC2  push XHL
	cps	bc, 0	; F63BC3  cp BC,0
	jr	z, 26	; F63BC5  jr Z,0xf63be1
	ldda32	xhl, (3171)	; F63BC7  ld XHL,(0x0c63)
