	subda32	xiy, (3171)	; F63BD9  sub XIY,(0x0c63)
	subda32	xix, (3161)	; F63BDD  sub XIX,(0x0c59)
	pop	xhl	; F63BE1  pop XHL
	pop	xde	; F63BE2  pop XDE
	popw	wa	; F63BE3  pop WA
	ret	; F63BE4  ret

